import{_ as o,r as s,o as p,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"ajaxHandler() - October CMS - 4.x","titleTemplate":false,"description":"Twig Function","frontmatter":{"subtitle":"Twig Function"},"headers":[{"level":2,"title":"Accessing Data","slug":"accessing-data","link":"#accessing-data","children":[]},{"level":2,"title":"Using Responses","slug":"using-responses","link":"#using-responses","children":[]},{"level":2,"title":"Handling Errors","slug":"handling-errors","link":"#handling-errors","children":[]},{"level":2,"title":"Handling Redirects","slug":"handling-redirects","link":"#handling-redirects","children":[]},{"level":2,"title":"Handling Flash Messages","slug":"handling-flash-messages","link":"#handling-flash-messages","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/markup/function/ajax-handler.md","filePath":"4.x/markup/function/ajax-handler.md"}'),r={name:"4.x/markup/function/ajax-handler.md"};function u(d,n,g,k,h,w){const t=s("pre-heading"),e=s("post-heading");return p(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"ajaxHandler()",-1)),a(e),n[1]||(n[1]=i(`<p>The <code>ajaxHandler()</code> function runs an AJAX handler inside Twig and prepares a <code>Cms\\Classes\\AjaxResponse</code> response object. An example of calling an <strong>onResetPassword</strong> handler.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> result <span class="token operator">=</span> ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The following properties can be expected in the resulting object.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Data</th></tr></thead><tbody><tr><td><strong>data</strong></td><td>data set or returned by the handler, also available by directly calling the object.</td></tr><tr><td><strong>error</strong></td><td>an error was thrown during the handler execution.</td></tr><tr><td><strong>flash</strong></td><td>flash messages set by the handler.</td></tr><tr><td><strong>redirect</strong></td><td>the handler returned a redirect.</td></tr></tbody></table></div><h2 id="accessing-data"><a href="#accessing-data" class="header-anchor">#</a> Accessing Data</h2><p>Variables assigned to the page are available to the resulting object. Take the following AJAX handler definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onResetPassword</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;someVariable&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;someValue&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Next is an, an example of calling the <strong>onResetPassword</strong> handler.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> result <span class="token operator">=</span> ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <strong>data</strong> variables returned from the handler or set on the page during the handler call will be available via resulting variable.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result<span class="token punctuation">.</span>someVariable <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="using-responses"><a href="#using-responses" class="header-anchor">#</a> Using Responses</h2><p>When <a href="./../../cms/resources/building-apis.html">building APIs in your theme</a>, the response can be passed directly to the <code>response()</code> <a href="./response.html">Twig function</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>When returning as a response, the data will be available in JSON as the <strong>data</strong> property.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The page variables are not included with the response for security reasons. Call the <code>withPageVars</code> method to include them with the response.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>withPageVars<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The <code>withVars</code> method can be used to include additional data with the response.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onResetPassword<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>withVars<span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token string"><span class="token punctuation">&#39;</span>token<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>foobar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="handling-errors"><a href="#handling-errors" class="header-anchor">#</a> Handling Errors</h2><p>If an exception occurs during the handler, the error message will be available in the <strong>error.message</strong> property. If the error is a <code>ValidationException</code> then the invalid fields can be found in the <strong>error.fields</strong> property.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> result<span class="token punctuation">.</span>error <span class="token delimiter punctuation">%}</span></span>
    An error occurred: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result<span class="token punctuation">.</span>error<span class="token punctuation">.</span>message <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>If an exception occurs, the error information will be available as the <strong>error</strong> property.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;error&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;An error occurred&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>When returning a response from an AJAX handler, the following status codes are used for the exception type.</p><div class="table"><table tabindex="0"><thead><tr><th>Exception</th><th>Status Code</th></tr></thead><tbody><tr><td><code>ValidationException</code></td><td>422 Unprocessable Entity</td></tr><tr><td><code>ApplicationException</code></td><td>400 Bad Request</td></tr><tr><td><code>Exception</code></td><td>500 Internal Server Error</td></tr></tbody></table></div><h2 id="handling-redirects"><a href="#handling-redirects" class="header-anchor">#</a> Handling Redirects</h2><p>If the AJAX handler caused a redirect, this will be available on the <strong>redirect</strong> property and can be returned directly. For example</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirect</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://octobercms.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The following will redirect to the browser as a response.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onTest<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The object contains the <strong>redirect</strong> messages alongside the data.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;redirect&quot;</span><span class="token operator">:</span> <span class="token string">&quot;https://octobercms.com&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="handling-flash-messages"><a href="#handling-flash-messages" class="header-anchor">#</a> Handling Flash Messages</h2><p>If flash messages were used, these will be available in the <strong>flash</strong> property. Take the following handler as an example.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Flash</span><span class="token operator">::</span><span class="token function">success</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Test successful&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Calling the handler and sending as a response.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> response<span class="token punctuation">(</span>ajaxHandler<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onTest<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The output contains the <strong>flash</strong> messages alongside the data.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;flash&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;success&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Test successful&quot;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../cms/resources/building-apis.html">Building API Resources</a></li></ul></div>`,43))])}const v=o(r,[["render",u]]);export{f as __pageData,v as default};
